'use strict';
function ensureProductState(){state.product=state.product||{service:'mental-health',theme:'light',role:'clinician',extensions:{},team:'Proposed pilot team',contact:'To be nominated',pilotNotes:'',planNotes:{}};state.product.extensions=state.product.extensions||{};state.product.planNotes=state.product.planNotes||{};}
ensureProductState();
const baseRender=render;
render=function(){ensureProductState();document.documentElement.dataset.theme=state.product.theme;document.documentElement.style.colorScheme=state.product.theme;const custom={organisation:organisationPage,extensions:extensionsPage,connections:connectionsPage,delivery:deliveryPage};baseRender();if(custom[route])document.getElementById('main').innerHTML=custom[route]();const bc=document.querySelector?.('.breadcrumb b');if(bc&&custom[route])bc.textContent={organisation:'Organisation setup',extensions:'DeepSynaps extensions',connections:'Connection centre',delivery:'Oxford Health delivery plan'}[route];const header=document.getElementById('topbar');header.insertAdjacentHTML?.('beforeend',`<button class="top-icon theme-control" onclick="toggleTheme()" aria-label="Switch to ${state.product.theme==='light'?'dark':'light'} theme" title="Switch colour theme">${state.product.theme==='light'?'☾':'☀'}</button>`);};
renderSidebar=function(){ensureProductState();document.getElementById('sidebar').innerHTML=`<div class="brand"><img class="real-logo" src="assets/deepsynaps-logo.svg" alt="DeepSynaps neuron logo"><div><strong>DeepSynaps</strong><small>CLINICAL ADMIN</small></div></div><button class="org org-button" onclick="nav('organisation')"><span class="organisation-initial">OH</span><span><strong>Oxford Health</strong><small>NHS Foundation Trust</small><em>Proposed pilot workspace</em></span></button><nav aria-label="Main navigation"><div class="nav-label">WORKSPACE</div>${navButton('home','grid','Today')}${navButton('patients','people','Patients & appointments')}${['C','N','F','T','E'].map(key=>{const c=catFor(key);return navButton(key,c.icon,c.short)}).join('')}<div class="nav-label">ORGANISATION</div>${navButton('extensions','spark','DeepSynaps extensions')}${navButton('connections','link','Connection centre')}${navButton('NHS','shield','Governance & assurance')}${navButton('organisation','settings','Organisation setup')}<div class="nav-label">PILOT PREPARATION</div>${navButton('delivery','check','Delivery plan')}${navButton('catalogue','grid','All 158 functions')}${navButton('settings','settings','Demo settings')}</nav><div class="side-bottom"><div class="connected"><span class="demo-dot"></span> SYNTHETIC DEMONSTRATION<strong>Clinical OS API not connected</strong></div><div class="profile"><div class="avatar">JM</div><div>Dr Jamie Morgan<small>Fictional clinician · Local preview</small></div></div></div>`};
function toggleTheme(){state.product.theme=state.product.theme==='dark'?'light':'dark';save();render()}
function service(){return serviceProfiles.find(s=>s.id===state.product.service)||serviceProfiles[0]}
function home(){ensureProductState();const done=state.tasks.filter(t=>t.done).length;const open=state.tasks.length-done;return head('Your day, connected.','Clinical documentation, patient administration and coordinated care.',`<button class="button-icon" onclick="startTour()">${icon('play')} Guided tour</button><button class="primary button-icon" onclick="nav('C')">${icon('plus')} New consultation</button>`,'DEEPSYNAPS CLINICAL ADMIN')+`<div class="trust-context"><div><span class="context-kicker">PROPOSED WORKSPACE FOR</span><strong>Oxford Health NHS Foundation Trust</strong><p>${service().name} · ${esc(state.product.team)}</p></div><button onclick="nav('organisation')">Configure workspace ${icon('settings')}</button></div><div class="stats"><button class="stat first" onclick="nav('patients')"><div class="stat-top">Today’s appointments ${icon('calendar')}</div><div class="stat-value">3</div><div class="stat-bottom">Fictional clinic · 13 October</div></button><button class="stat" onclick="nav('T')"><div class="stat-top">Open team tasks ${icon('check')}</div><div class="stat-value">${open}</div><div class="stat-bottom">${done} completed in this walkthrough</div></button><button class="stat" onclick="nav('N')"><div class="stat-top">Documents to review ${icon('file')}</div><div class="stat-value">${state.note&&!state.signed?1:0}</div><div class="stat-bottom">${state.signed?'1 demo note signed':'Clinician review before signing'}</div></button><button class="stat" onclick="nav('connections')"><div class="stat-top">Live connections ${icon('link')}</div><div class="stat-value">0</div><div class="stat-bottom">Explore the verified API contracts</div></button></div><div class="content-grid"><section><div class="section-head"><div><h2>Your clinical workspace</h2><p>Start with the task in front of you.</p></div><button class="text-btn" onclick="catalogue()">All 158 functions ↗</button></div><div class="category-grid">${['C','N','F','T','E','I'].map(key=>{const c=catFor(key);return `<button class="category-card" onclick="nav('${key}')"><span class="card-arrow">${icon('arrow')}</span><div class="card-icon ${c.color}">${icon(c.icon)}</div><h3>${c.name}</h3><p>${c.desc}</p><div class="card-foot"><span>${count(null,key)} capabilities</span><span>·</span><span>${key==='I'?'Handoff preview':'Interactive demo'}</span></div></button>`}).join('')}</div><div class="journey">${icon('spark')}<div><h3>Extend your workspace when you need to</h3><p>Explore evidence, outcomes, patient context and specialist report access.</p></div><button onclick="nav('extensions')">Explore extensions ↗</button></div><div class="inventory-strip"><button onclick="catalogue('operational')"><strong>91</strong> reported operational</button><button onclick="catalogue('linked')"><strong>31</strong> linked modules</button><button onclick="catalogue('pending')"><strong>36</strong> pending or excluded</button><span>Repository register · Source reviewed</span></div></section><aside class="right-rail"><div class="panel"><div class="panel-head"><h3>Today’s clinic</h3><span class="pill grey">Fictional</span></div><div class="day">${icon('calendar')} Tuesday, 13 October</div>${appointment('09:15','MC','Maya Collins',service().template,true)}${appointment('10:00','AT','Alex Taylor','Initial consultation',false)}${appointment('10:45','SW','Sam Wilson','Care plan review',false)}<button class="wide" onclick="nav('patients')">Open appointment list →</button></div><div class="panel pilot-card"><span class="eyebrow">OXFORD HEALTH PROPOSAL</span><h3>From demonstration to pilot</h3><p class="fine">Six delivery phases, 30 work packages and a clear boundary between prototype work and live deployment.</p><button class="primary wide" onclick="nav('delivery')">Open delivery plan</button><button class="text-btn" style="margin-top:12px" onclick="nav('connections')">What can the API do today? ↗</button></div><div class="notice">Prepared for discussion with Oxford Health. No Trust commissioning, partnership or approval is claimed.</div></aside></div>`}
function organisationPage(){const p=state.product;return head('An organisation-shaped workspace.','Configure the proposed pilot experience. These settings remain in this browser.',`<button class="button-icon" onclick="exportConfiguration()">${icon('download')} Export proposal</button>`)+`<div class="work-grid"><section class="panel"><div class="panel-head"><h2>Oxford Health NHS Foundation Trust</h2><span class="pill amber">Proposed</span></div><p class="fine">The Trust provides physical, mental health and social care. These initial service profiles are our product proposals, not confirmed Trust requirements. <a href="https://www.oxfordhealth.nhs.uk/about-us/" target="_blank" rel="noopener noreferrer">Trust overview ↗</a></p><form onsubmit="event.preventDefault();saveOrganisation(this)"><div class="form-group"><label for="service-profile">Proposed first service</label><select class="field" id="service-profile" name="service">${serviceProfiles.map(s=>`<option value="${s.id}" ${p.service===s.id?'selected':''}>${s.name}</option>`).join('')}</select></div><div class="form-group"><label for="pilot-team">Pilot team label</label><input class="field" id="pilot-team" name="team" maxlength="80" required value="${esc(p.team)}"></div><div class="form-group"><label for="pilot-owner">Clinical sponsor / accountable owner</label><input class="field" id="pilot-owner" name="contact" maxlength="100" value="${esc(p.contact)}" placeholder="To be nominated"></div><div class="form-group"><label for="pilot-notes">Pilot objectives and open questions</label><textarea class="field" id="pilot-notes" name="notes" rows="4" maxlength="1500" placeholder="Use proposal information only; no patient data.">${esc(p.pilotNotes)}</textarea></div><button class="primary">Save proposal configuration</button></form></section><aside><div class="panel"><h3>Decisions to agree with the Trust</h3>${['First service and pilot team','EPR and staff identity requirements','Baseline workflow and pilot measures','Hosting and approved data processors','Clinical safety and information governance owners'].map((t,i)=>`<div class="audit-row"><span class="step-number">${i+1}</span><span>${t}</span></div>`).join('')}<button class="wide" onclick="nav('delivery')">Review delivery work packages →</button></div><div class="panel"><h3>Product principles</h3><p class="fine">One core workspace. Optional extensions. Clinician-reviewed documents. Server-enforced access in the connected product.</p><button class="wide" onclick="nav('extensions')">Choose proposed extensions</button></div></aside></div>`}
function saveOrganisation(form){state.product.service=form.service.value;state.product.team=form.team.value.trim()||'Proposed pilot team';state.product.contact=form.contact.value.trim()||'To be nominated';state.product.pilotNotes=form.notes.value.trim();const saved=audit('Oxford Health proposal configuration saved locally.');render();toast(saved?'Proposal saved. No Trust settings or live systems changed.':'Proposal remains in this tab only. Saving failed.')}
function extensionsPage(){const suggested=service().suggested;return head('DeepSynaps extensions','Add the capabilities your service needs, through an organisation-controlled request process.',`<button onclick="nav('organisation')">${service().name} profile</button>`)+`<div class="notice">Requests and previews below are local demonstrations. A live extension requires an approved scope, API access and server-enforced entitlement. No specialist clinical service is activated here.</div><div class="extension-grid">${extensions.map(e=>{const requested=state.product.extensions[e.id]?.requested;return `<article class="panel extension-card"><div class="panel-head"><span class="card-icon ${e.group==='Specialist'?'violet':'teal'}">${icon(e.icon)}</span><span class="pill ${requested?'blue':e.group==='Specialist'?'amber':'grey'}">${requested?'Request drafted':e.group==='Specialist'?'Separate assessment':e.group}</span></div><h2>${e.title}</h2><p>${e.description}</p><div class="extension-meta">${suggested.includes(e.id)?'<span class="pill green">Suggested for this profile</span>':'<span class="fine">Optional extension</span>'}<span class="fine">${e.ids.join(' · ')}</span></div><div class="actions"><button class="primary" onclick="requestExtension('${e.id}')">${requested?'Edit request':'Request extension'}</button><button onclick="previewExtension('${e.id}')">View example</button></div></article>`}).join('')}</div><div class="panel"><h3>Clinical boundaries remain in place</h3><p class="fine">Twins, patient-specific diagnosis or treatment recommendations, autonomous prescribing, unsupervised risk triage and self-training on identifiable NHS records are outside this documentation pilot. Specialist studios require a separately agreed scope.</p><button class="text-btn" onclick="catalogue('excluded')">View excluded functions ↗</button></div>`}
function requestExtension(id){const e=extensions.find(e=>e.id===id);const r=state.product.extensions[id];modal('Request: '+e.title,`<p>${e.description}</p><div class="notice">${e.scope}</div><p class="fine"><strong>Before activation:</strong> ${e.dependencies}</p><label for="extension-reason" class="fine">Why would this help the proposed pilot?</label><textarea class="field" id="extension-reason" rows="3" maxlength="500" style="width:100%;margin-top:8px">${esc(r?.reason||'')}</textarea><p class="fine">Saved locally as a draft request. No email, purchase or activation occurs.</p>`,`<button onclick="closeModal()">Cancel</button>${r?.requested?`<button onclick="delete state.product.extensions['${id}'];audit('Local extension request withdrawn.');closeModal();render()">Withdraw</button>`:''}<button class="primary" onclick="saveExtensionRequest('${id}')">Save draft request</button>`)}
function saveExtensionRequest(id){state.product.extensions[id]={requested:true,reason:document.getElementById('extension-reason').value.trim(),date:new Date().toISOString()};const saved=audit('Local extension request drafted: '+extensions.find(e=>e.id===id).title);closeModal();render();toast(saved?'Request drafted locally. Extension remains unconnected.':'Request remains in this tab only. Saving failed; nothing was sent.')}
function previewExtension(id){const e=extensions.find(e=>e.id===id);const examples={evidence:'A clinician opens a source result, checks its date and relevance, and keeps its citation alongside the draft. No search or clinical evidence is generated in this preview.',timeline:'Fictional sequence: appointment booked → patient priority recorded → consultation reviewed → follow-up task assigned.',outcomes:'Patient-stated goal: discuss how sleep affects the working day. Next administrative step: arrange a review of the diary. No outcome improvement is claimed.', 'patient-app':'A reviewed form or summary is prepared for the patient. Delivery requires an authorised patient identity and an approved channel.',cognitive:'A report card would show assessment name, licensed instrument version, author, date and source. No score or diagnostic interpretation is fabricated.',qeeg:'A report card would show recording identity, quality review, report author and clinical review status. No stimulation protocol is generated.',wearables:'An approved summary would show device, collection dates, missingness and sharing consent. No real wearable is connected.',assistant:'Example administrative request: “Show the unsigned documents assigned to me.” Only authorised records would be returned.'};modal(e.title+' — workflow example',`<span class="pill grey">Illustrative example</span><p>${examples[id]}</p><div class="notice">${e.scope}</div><p class="fine">${e.dependencies}</p>`,`<button onclick="closeModal()">Close</button><button class="primary" onclick="requestExtension('${id}')">Draft extension request</button>`)}
function connectionsPage(){return head('Connection centre','A clear view of the Clinical OS integration boundaries.',`<button class="button-icon" onclick="connectionReadiness()">${icon('shield')} Inspect setup</button>`)+`<div class="connection-summary"><div><span class="pill amber">Not connected</span><h2>Clinical OS connection</h2><p>Repository contracts inspected. No staging API origin, authenticated session or server-side sandbox key has been configured for this site.</p></div><div class="connection-stamp">API<br><strong>0</strong><small>live connections</small></div></div><div class="category-grid" style="margin:22px 0"><div class="panel"><div class="eyebrow">READ INTEGRATION</div><h2>Partner API</h2><p class="fine">Read-only FHIR R4 access to authorised handovers, referrals and signed documents. Sandbox keys are limited to synthetic records.</p><code>/api/partner/v1</code><button class="wide" onclick="connectionDetail('partnerMeta')">Explore partner metadata contract</button></div><div class="panel"><div class="eyebrow">WORKSPACE WORKFLOWS</div><h2>Authenticated Clinical OS API</h2><p class="fine">Drafts, notes, consent, forms and handovers need the authenticated workspace services. A partner key does not grant these write operations.</p><code>/api/v1/clinical-workspace</code><button class="wide" onclick="connectionDetail('drafts')">Explore draft-generation boundary</button></div></div><div class="section-head"><div><h2>Verified integration map</h2><p>Verified here means source or contract inspected, not a successful live API test.</p></div><button class="text-btn" onclick="download('clinical-admin-api-map.json',JSON.stringify(integrationContracts,null,2),'application/json')">Export map ↗</button></div><div class="table-wrap"><table><thead><tr><th>Method</th><th>Operation</th><th>Authentication</th><th>Details</th></tr></thead><tbody>${integrationContracts.map(c=>`<tr><td>${c.method}</td><td><strong>${c.purpose}</strong><br><code class="api-path">${c.path}</code></td><td>${c.auth}</td><td><button class="text-btn" onclick="connectionDetail('${c.key}')">Inspect ↗</button></td></tr>`).join('')}</tbody></table></div><div class="journey">${icon('link')}<div><h3>NHS and EPR connection</h3><p>Trust requirements and vendor authorisation must be confirmed before any live connector is enabled.</p></div><button onclick="nav('I')">View handoff preview →</button></div>`}
function connectionReadiness(){modal('Connection setup inspection',`<p>This inspection checks the configuration shipped with this site. It does not make a network health request.</p><dl><dt>Site mode</dt><dd>Synthetic browser-local demonstration</dd><dt>Source review</dt><dd>Workspace routers and partner OpenAPI inspected at commit <code>2be80acd</code></dd><dt>API origin</dt><dd>Not configured</dd><dt>User session</dt><dd>No Clinical OS session integration</dd><dt>Partner key</dt><dd>Not configured; keys belong in a server secret store</dd><dt>Adapter</dt><dd>Server-only read adapter and session/tenant/patient gateway policy included in the source repository; not mounted or deployed</dd><dt>Write actions</dt><dd>Not connected. Require authenticated workspace integration.</dd></dl><div class="notice">The next connection milestone is an approved synthetic staging environment and an authenticated test account. No key-entry field is exposed in this browser.</div>`)}
function connectionDetail(key){const c=integrationContracts.find(c=>c.key===key);modal(c.purpose,`<span class="pill blue">${c.method}</span><p><code>${c.path}</code></p><dl><dt>Authentication</dt><dd>${c.auth}</dd><dt>Evidence</dt><dd>${c.status}</dd><dt>Runtime</dt><dd>Not connected in this prototype</dd></dl><p>${c.method==='POST'?'A write must carry the real user’s identity and pass the existing tenant, role, consent and processing gates. The read-only partner adapter intentionally cannot issue this request.':'The server-only adapter uses an explicit operation allowlist and preserves upstream denials. No failed live read is replaced with sample patient data.'}</p><button class="text-btn" onclick="closeModal();nav('delivery')">See integration work packages ↗</button>`)}
function deliveryPage(){return head('Oxford Health delivery plan','Six phases. Thirty work packages. Evidence before activation.',`<a class="button-link" href="Oxford_Health_Clinical_Admin_Implementation_Plan.md" download>${icon('download')} Download detailed plan</a>`)+`<div class="plan-summary"><div><span class="eyebrow">CURRENT MILESTONE</span><h2>Branded prototype + integration foundation</h2><p>The product interface and delivery plan are published. Clinical OS source contracts have been reviewed. Live API connection, Trust approval and real-patient deployment remain outstanding.</p></div><button onclick="nav('connections')">Connection requirements →</button></div><div class="phase-grid">${deliveryPhases.map((p,i)=>`<section class="panel phase-panel"><div class="panel-head"><span class="phase-number">0${i+1}</span><span class="fine">${p.items.length} work packages</span></div><h2>${p.name}</h2><p class="fine">${p.summary}</p>${p.items.map(item=>`<button class="work-package" onclick="workPackage('${item[0]}')"><span class="work-id">${item[0]}</span><span><strong>${item[1]}</strong><small>${item[2]}</small></span><span>↗</span></button>`).join('')}</section>`).join('')}</div><div class="notice">Software changes and source review do not complete clinical, information-governance or Trust approvals. Those require accountable people and evidence for the exact release.</div>`}
function workPackage(id){const phase=deliveryPhases.find(p=>p.items.some(i=>i[0]===id));const item=phase.items.find(i=>i[0]===id);modal(item[0]+' · '+item[1],`<span class="pill ${item[2].includes('Applied')||item[2].includes('reviewed')?'green':'amber'}">${item[2]}</span><p>${item[3]}</p><label class="fine" for="package-note">Local planning note — does not approve or complete this gate</label><textarea id="package-note" class="field" rows="4" style="width:100%;margin-top:8px" maxlength="1000">${esc(state.product.planNotes[id]||'')}</textarea>`,`<button onclick="closeModal()">Close</button><button onclick="addPlanTask('${id}')">Add follow-up task</button><button class="primary" onclick="savePlanNote('${id}')">Save planning note</button>`)}
function savePlanNote(id){state.product.planNotes[id]=document.getElementById('package-note').value.trim();const saved=save();closeModal();toast(saved?'Planning note saved locally. Gate status is unchanged.':'Planning note remains in this tab only. Saving failed.')}
function addPlanTask(id){const item=deliveryPhases.flatMap(p=>p.items).find(i=>i[0]===id);const text=id+': '+item[1];if(!state.tasks.some(t=>t.text===text)){state.tasks.push({text,owner:'Admin team',done:false});audit('Delivery follow-up task added: '+id);}closeModal();nav('T')}
function exportConfiguration(){download('oxford-health-clinical-admin-proposal.json',JSON.stringify({product:productConfig.name,organisation:productConfig.organisation,status:'PROPOSAL_ONLY',service:service(),team:state.product.team,owner:state.product.contact,notes:state.product.pilotNotes,extensionRequests:state.product.extensions,planningNotes:state.product.planNotes,liveConnections:false,sourceCommit:productConfig.sourceCommit},null,2),'application/json')}
intelligence=function(){return extensionsPage()};
showAbout=function(){modal('DeepSynaps Clinical Admin',`<p>A standalone product concept powered by the Clinical Intelligence OS, tailored here for a <strong>proposed Oxford Health NHS Foundation Trust pilot</strong>.</p><p>This site uses fictional records and local browser storage. It is not a commissioned Trust system and no NHS approval or partnership is claimed.</p><p>The 158-function register was inspected in <a href="https://github.com/ALIYILD/DeepSynaps-Clinical-Intelligence-OS/blob/2be80acd1ac68b01756c1acccad8010363755389/docs/clinical-workspace/FUNCTION_STATUS.md" target="_blank" rel="noopener noreferrer">the Clinical OS repository</a>. Exact titles, status counts and implementation limitations are reflected in this site. Cited upstream tests were not rerun here.</p><p>The partner API is read-only. Authenticated workspace services are needed for writes. No API, AI provider, SMS, microphone or EPR is connected in this prototype.</p><p>The actual DeepSynaps logo and design tokens come from the main Clinical OS. The Oxford Health name identifies the intended audience, not an endorsement.</p>`,`<button onclick="closeModal()">Close</button><button class="primary" onclick="closeModal();nav('delivery')">Open implementation plan</button>`)};
const priorSettings=settingsPage;
settingsPage=function(){return priorSettings()+`<div class="panel"><h3>Appearance & product configuration</h3><p class="fine">Choose the DeepSynaps light or dark workspace. Organisation and extension settings are managed separately.</p><div class="actions"><button onclick="toggleTheme()">Switch to ${state.product.theme==='light'?'dark':'light'} mode</button><button onclick="nav('organisation')">Organisation setup</button><button onclick="nav('extensions')">Extension requests</button></div></div>`};
const productRoute=location.hash.slice(1);if(['organisation','extensions','connections','delivery'].includes(productRoute))route=productRoute;
render();
